before:
Complete local Go example; the app itself does not execute it:
```go
package main

import (
	"fmt"
)

func main() {
	values := []int{2, 4}
	for i, value := range values {
		value += 1
		fmt.Println(i, value)
	}
	fmt.Println(values)
}

```

